<script setup lang="ts">
import { ui } from "../ui"
import DateTime from './DateTime.vue'
import {ref,onMounted} from 'vue'
import {api,bootstrap} from '../composables/api'
import type {OperationsStatus} from '../types'
const props=defineProps<{compact?:boolean}>(),data=ref<OperationsStatus|null>(null),loading=ref(false),error=ref('')
async function reload(){loading.value=true;try{data.value=await api('/operations');error.value=''}catch(e){error.value=e instanceof Error?e.message:'Operations could not be inspected.'}finally{loading.value=false}}
onMounted(reload)
</script>
<template><section :class="ui('$all', '$section', 'operations-panel')"><div :class="ui('$all', '$div', 'section-heading')"><div :class="ui('$all', '$div')"><h2 :class="ui('$all', '$h2')">{{compact?'Processing and maintenance':'Operations & maintenance'}}</h2><p :class="ui('$all', '$p', 'help')">Actual observations, bounded retention and deployment-only purge.</p></div><button :class="ui('$all', '$button', 'button')" :disabled="loading" @click="reload">{{loading?'Refreshing…':'Refresh observations'}}</button></div><p :class="ui('$all', '$p')" v-if="loading&&!data" role="status">Loading operational evidence…</p><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert">{{error}}<button :class="ui('$all', '$button', 'button')" @click="reload">Retry inspection</button></div><template v-if="data"><div v-if="data.state!=='active'" :class="ui('$all', '$div', 'notice warning')"><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">Installation {{data.state}}</strong><p :class="ui('$all', '$p')">New capture and provider claims are stopped. Existing leased calls may complete while draining; accepted external messages cannot be recalled. Resume the same deployment purge run.</p></div></div><div v-if="!data.schema.ready" :class="ui('$all', '$div', 'notice danger')">Run the package installer and migrations. Missing tables: {{data.schema.missing.join(', ')}}</div><p :class="ui('$all', '$p', 'help spacing')">{{data.offline_note}}</p>
<div :class="ui('$all', '$div', 'table-scroll operational-observations')" tabindex="0" role="region" aria-label="Operational observations, scroll for timestamps"><table :class="ui('$all', '$table')"><caption :class="ui('$all', '$caption', 'sr-only')">Operational observations</caption><thead :class="ui('$all', '$thead')"><tr :class="ui('$all', '$tr')"><th scope="col" :class="ui('$all', '$th')">Operation</th><th scope="col" :class="ui('$all', '$th', 'table-time')">Last start</th><th scope="col" :class="ui('$all', '$th', 'table-time')">Last success</th><th scope="col" :class="ui('$all', '$th')">Result</th></tr></thead><tbody :class="ui('$all', '$tbody')"><tr :class="ui('$all', '$tr')" v-for="o in data.observations" :key="o.key"><td :class="ui('$all', '$td')"><strong :class="ui('$all', '$strong')">{{o.label}}</strong><p :class="ui('$all', '$p', 'help')">{{o.detail}}</p><details v-if="o.history.length" :class="ui('$all', '$details', 'operation-history')"><summary :class="ui('$all', '$summary')">Recent maintenance runs</summary><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="h in [...o.history].reverse()" :key="h.id"><strong :class="ui('$all', '$strong')">{{h.state}}</strong> · <DateTime :class="ui('$all', '$DateTime')" :value="h.completed_at"/><span :class="ui('$all', '$span')" v-if="Object.keys(h.counts).length"> · {{Object.entries(h.counts).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · ')}}</span></li></ul></details><p v-if="o.last_failure_at" :class="ui('$all', '$p', 'help')">Last failure: <DateTime :class="ui('$all', '$DateTime')" :value="o.last_failure_at"/></p></td><td :class="ui('$all', '$td', 'table-time')"><DateTime :class="ui('$all', '$DateTime')" :value="o.last_started_at"/></td><td :class="ui('$all', '$td', 'table-time')"><DateTime :class="ui('$all', '$DateTime')" :value="o.last_success_at"/><small :class="ui('$all', '$small')">{{o.fresh?'Within observation window':'No current completion proof'}}</small></td><td :class="ui('$all', '$td')"><span :class="ui('$all', '$span', 'badge', (o.state))" >{{o.state==='running'?'Started':o.state}}</span></td></tr></tbody></table></div>
<details :class="ui('$all', '$details', 'operations-section')" :open="compact"><summary :class="ui('$all', '$summary', 'operations-disclosure-title')">Deployment checklist</summary><p :class="ui('$all', '$p', 'help')">Workers and scheduled commands are host-managed. These are commands to deploy, not actions this page runs.</p><div :class="ui('$all', '$div', 'deployment-commands')"><div :class="ui('$all', '$div')"><h4 :class="ui('$all', '$h4')">Queue workers</h4><pre :class="ui('$all', '$pre')">{{data.commands.capture_worker}}
{{data.commands.delivery_worker}}</pre></div><div :class="ui('$all', '$div')"><h4 :class="ui('$all', '$h4')">Scheduled maintenance</h4><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')">Every minute: <code :class="ui('$all', '$code')">telescope-monitor:heartbeat</code></li><li :class="ui('$all', '$li')">Every minute: <code :class="ui('$all', '$code')">telescope-monitor:recover --limit=100</code></li><li :class="ui('$all', '$li')">Every minute: <code :class="ui('$all', '$code')">telescope-monitor:recover-deliveries --limit=100</code></li><li :class="ui('$all', '$li')">Every five minutes: <code :class="ui('$all', '$code')">telescope-monitor:reconcile --limit=100</code></li><li :class="ui('$all', '$li')">Hourly: <code :class="ui('$all', '$code')">telescope-monitor:prune --limit=1000</code></li><li :class="ui('$all', '$li')">Every minute: <code :class="ui('$all', '$code')">telescope-monitor:expire-snoozes --limit=100</code></li></ul></div></div><p :class="ui('$all', '$p', 'help')">Use the configured queue connection and names. Queue retry/visibility time must exceed the worker timeout. A command start or heartbeat does not prove the other tasks succeeded.</p></details>
<template v-if="!compact"><section :class="ui('$all', '$section', 'operations-section')"><h3 :class="ui('$all', '$h3')">Source coverage</h3><p :class="ui('$all', '$p')">{{data.source.detail}}</p><dl :class="ui('$all', '$dl', 'context-list')"><div :class="ui('$all', '$div')" v-if="data.source.epoch"><dt :class="ui('$all', '$dt')">Source epoch</dt><dd :class="ui('$all', '$dd', 'code')">{{data.source.epoch}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Checkpoint / current maximum</dt><dd :class="ui('$all', '$dd')">{{data.source.checkpoint??'Unavailable'}} / {{data.source.maximum??'Unavailable'}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Ingestion floor</dt><dd :class="ui('$all', '$dd')">{{data.source.floor??'Unavailable'}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Protected time cutoff</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.source.cutoff"/></dd></div></dl><details :class="ui('$all', '$details')"><summary :class="ui('$all', '$summary')">Reset or replaced Telescope storage?</summary><p :class="ui('$all', '$p', 'help')">Rebaselining is an explicitly confirmed deployment action. It excludes existing source rows, changes the source epoch and keeps prior time protection. It preserves monitor error data and does not create historical alerts.</p><pre :class="ui('$all', '$pre')">{{data.commands.source_baseline}} --preview
{{data.commands.source_baseline}}</pre></details></section><section :class="ui('$all', '$section', 'operations-section')"><h3 :class="ui('$all', '$h3')">Credential availability</h3><p :class="ui('$all', '$p')"><span :class="ui('$all', '$span', 'badge', (data.credentials.state))" >{{data.credentials.state}}</span> {{data.credentials.checked}} active revisions checked · {{data.credentials.unreadable}} unreadable</p><p :class="ui('$all', '$p', 'help')">{{data.credentials.detail}}</p><RouterLink to="/integrations" :class="ui('$all', '$a', 'text-link')">Review connection configuration</RouterLink><details :class="ui('$all', '$details', 'spacing')"><summary :class="ui('$all', '$summary')">Rotate the host encryption key safely</summary><p :class="ui('$all', '$p', 'help')">Configure the current key and previous keys in the host first. Rewrap bounded pages for secrets, inbox, evidence, events, deliveries and notes. Keep previous keys until every target finishes. Logical bytes, digests, key IDs and revisions stay fixed; unreadable ciphertext is preserved and reported.</p><pre :class="ui('$all', '$pre')">{{data.commands.key_rewrap}}</pre><p :class="ui('$all', '$p', 'help')">Resume each target with the returned next_cursor as --after. If any value failed, restore the required key and retry from cursor zero. Do not remove a previous key after rewrapping secrets alone.</p></details></section><details :class="ui('$all', '$details', 'operations-section purge-guidance')" :open="data.state!=='active'"><summary :class="ui('$all', '$summary', 'operations-disclosure-title')">Whole-installation purge<span v-if="data.purge" :class="ui('$all', '$span', 'badge')">{{data.purge.state}}</span></summary><p :class="ui('$all', '$p')">Purge is a deployment command, requiring the installation identifier as explicit confirmation. It deletes error evidence, summaries, counts, notes, activity, GitHub associations and delivery history. External messages, tickets and Telescope source remain untouched.</p><p :class="ui('$all', '$p', 'help')">Preserved: installation identity, configuration, connection credentials, alert rules, saved views/preferences and minimal command/purge receipts. The command drains active leases, advances the generation, records cutoffs and resumes deletion in bounded steps.</p><dl :class="ui('$all', '$dl', 'context-list')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Installation identifier</dt><dd :class="ui('$all', '$dd', 'code')">{{data.installation}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Current generation</dt><dd :class="ui('$all', '$dd')">{{data.generation}}</dd></div></dl><pre :class="ui('$all', '$pre')">{{data.commands.purge_preview}}</pre><template v-if="data.purge"><h4 :class="ui('$all', '$h4')">Latest purge run · {{data.purge.state}}</h4><dl :class="ui('$all', '$dl', 'context-list')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Run identifier</dt><dd :class="ui('$all', '$dd', 'code')">{{data.purge.id}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Current step</dt><dd :class="ui('$all', '$dd')">{{data.purge.step}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Started / completed</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.purge.started_at"/> / <DateTime :class="ui('$all', '$DateTime')" :value="data.purge.completed_at"/></dd></div><div :class="ui('$all', '$div')" v-if="data.purge.error"><dt :class="ui('$all', '$dt')">Safe diagnostic</dt><dd :class="ui('$all', '$dd')">{{data.purge.error}}</dd></div></dl><pre :class="ui('$all', '$pre')" v-if="['draining','purging'].includes(data.purge.state)">php artisan telescope-monitor:purge {{data.installation}} --confirm={{data.installation}} --resume={{data.purge.id}} --limit=500 --batches=1</pre><p :class="ui('$all', '$p', 'help')">{{Object.entries(data.purge.counts).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · ')||'No error-domain rows deleted yet.'}}</p></template><p v-else :class="ui('$all', '$p', 'help')">No purge run recorded. Previewing the deployment command does not delete data.</p></details></template><p v-else :class="ui('$all', '$p', 'help spacing')"><RouterLink to="/settings/operations" :class="ui('$all', '$a', 'text-link')">Open full operations and source-reset guidance</RouterLink></p><p :class="ui('$all', '$p', 'data-caption')">Observations as of <DateTime :class="ui('$all', '$DateTime')" :value="data.as_of"/>. An actual next scheduled run cannot be guaranteed from inside the host.</p></template></section></template>
